mapper.select:
select 
from media_person p
where p.id = #{id}

mapper.update:
update media_person
   set avatar_kind = #{avatarKind},
       avatar_ref  = #{avatarRef}
 where id = #{id}

mapper.select:
select count(*) from media_photo ph
where ph.album_id = #{albumId} and ph.seq = #{seq}
  and exists (
      select 1 from media_album al
      where al.id = ph.album_id
        and (al.person_id = #{personId}
             or exists (select 1 from media_album_person ap
                         where ap.album_id = al.id and ap.person_id = #{personId}))
  )

select count(*) from media_person
where id in
#{personId}

mapper.insert:
insert ignore into media_video_actor (video_id, name, person_id, role)
select #{videoId}, p.name, p.id, #{role}
from media_person p
where p.id = #{personId}

mapper.select:
select distinct person_id from media_video_actor
where person_id is not null and video_id in
#{videoId}

select distinct person_id from media_album_person
where album_id in
#{albumId}

select count(*) from (
    select album_id from media_album_person where person_id = #{personId}
    union
    select id from media_album where person_id = #{personId}
) t
